import{_ as p}from"./index-R2bOHvD3.js";import{d as b,E as v}from"./vendor-icons-CkkwuAC2.js";import{a as i,b as r,e,j as c,u as l,F as f,l as y,n as q,t as u,k as g,r as _}from"./vendor-vue-mUrA9Kfb.js";import"./vendor-axios-BOeqtr82.js";const A={class:"faq-view"},F={class:"faq-header"},h={class:"header-icon"},C={class:"faq-list"},w=["onClick"],M={class:"faq-question"},T={class:"question-text"},k={key:0,class:"faq-answer"},z={__name:"FAQView",setup(P){const a=_(null);function d(n){a.value=a.value===n?null:n}const m=[{question:"¿Cómo subir música a MelodyBox?",answer:'Ve a la sección "Subir" en el menú lateral, selecciona uno o más archivos de audio desde tu computadora y haz clic en "Subir". Los formatos compatibles son MP3, WAV, FLAC, OGG, M4A, AAC y WMA. Una vez subida, la canción se analizará automáticamente para mostrarte su espectro de frecuencia (FFT).'},{question:"¿Cómo descargar música de YouTube?",answer:'En la sección "Buscar", ingresa un término de búsqueda y ve a los resultados de YouTube. Puedes filtrar por duración (corto, medio, largo) y ordenar por relevancia, fecha o vistas. Selecciona el video que desees, elige formato (M4A o MP3) y calidad, y haz clic en "Descargar". La canción se agregará automáticamente a tu biblioteca.'},{question:"¿Qué es el análisis FFT y para qué sirve?",answer:"FFT (Fast Fourier Transform) es un análisis que descompone una canción en sus frecuencias componentes. Te permite visualizar el espectro de frecuencias (graves, medios y agudos) y ver un espectrograma que muestra cómo cambian las frecuencias a lo largo del tiempo. Es útil para entender la composición sonora de tus canciones y apreciar detalles del audio."},{question:"¿Cómo crear y gestionar playlists?",answer:'En la sección "Biblioteca", selecciona una o más canciones y haz clic en "Agregar a playlist". Puedes crear una playlist nueva o agregar a una existente. También puedes ir a la sección "Playlists" para ver, editar y organizar todas tus listas de reproducción.'},{question:"¿Qué formatos de audio son compatibles?",answer:"MelodyBox soporta los formatos MP3, WAV, FLAC, OGG, M4A, AAC y WMA. Para subir archivos desde tu computadora, todos estos formatos están permitidos. Las descargas de YouTube están disponibles en M4A y MP3 con varias calidades (128kbps, 192kbps, 256kbps y 320kbps)."},{question:"¿Cómo funciona el modo oscuro?",answer:"Puedes alternar entre modo claro y oscuro usando el botón de sol/luna que aparece en la esquina inferior izquierda de la barra lateral (o en el menú en dispositivos móviles). Tu preferencia se guarda automáticamente y se recordará en tu próxima visita."},{question:"¿Cómo buscar canciones en mi biblioteca?",answer:'En la sección "Biblioteca" puedes buscar canciones por nombre. También puedes navegar por todas tus canciones ordenadas alfabéticamente. Cada canción muestra información como artista, duración y si tiene análisis FFT disponible.'},{question:"¿Dónde se almacenan mis canciones?",answer:"Las canciones que subes o descargas se almacenan en el servidor en el directorio data/music/. Puedes acceder a ellas desde cualquier dispositivo iniciando sesión en tu cuenta de MelodyBox."}];return(n,s)=>(i(),r("div",A,[e("div",F,[e("div",h,[c(l(b),{size:28})]),s[0]||(s[0]=e("h1",{class:"page-title"},"Preguntas Frecuentes",-1)),s[1]||(s[1]=e("p",{class:"page-subtitle"},"Todo lo que necesitas saber sobre MelodyBox",-1))]),e("div",C,[(i(),r(f,null,y(m,(t,o)=>e("div",{key:o,class:q(["faq-item",{open:a.value===o}]),onClick:B=>d(o)},[e("div",M,[e("span",T,u(t.question),1),c(l(v),{size:20,class:"chevron"})]),a.value===o?(i(),r("div",k,[e("p",null,u(t.answer),1)])):g("",!0)],10,w)),64))])]))}},D=p(z,[["__scopeId","data-v-d83addb0"]]);export{D as default};
